package com.acme.billing

import com.acme.onboarding.internal.persistence.ApplicantRepository
import com.acme.onboarding.internal.persistence.ApplicantEntity
import com.acme.onboarding.internal.country.CountryRulesResolver
import org.springframework.scheduling.annotation.Scheduled
import org.springframework.stereotype.Component
import java.time.Clock
import java.time.LocalDate

@Component
class InvoiceScheduler(
    private val applicantRepository: ApplicantRepository,
    private val countryRules: CountryRulesResolver,
    private val invoiceService: InvoiceService,
    private val clock: Clock,
) {

    @Scheduled(cron = "0 0 6 * * *")
    fun issueDueInvoices() {
        val today = LocalDate.now(clock)
        applicantRepository.findAllByStatus("APPROVED")
            .filter { isBillable(it, today) }
            .forEach { invoiceService.issueFor(it.id, it.countryCode, it.billingDay) }
    }

    private fun isBillable(applicant: ApplicantEntity, today: LocalDate): Boolean {
        val rules = countryRules.resolve(applicant.countryCode)
        if (!rules.invoicingEnabled) return false
        if (applicant.kycStatus != "VERIFIED") return false
        return applicant.billingDay == today.dayOfMonth
    }
}
